#nullable enable // autogenerated

using MVZ2.GameContent.Seeds;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.loanSignStarshardDisable)]
    public class LoanSignStarshardDisableBuff : BuffDefinition
    {
        public LoanSignStarshardDisableBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new NamespaceIDModifier(LogicLevelProps.STARSHARD_DISABLE_ID, SetOperator.Set, VanillaBlueprintErrors.decrepify));
            AddModifier(new BooleanModifier(LogicLevelProps.STARSHARD_DISABLE_ICON, true));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer.RunToExpiredOrNull())
            {
                buff.Remove();
            }
        }
        public static void SetSeconds(Buff buff, float seconds)
        {
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(seconds);
                buff.SetProperty(PROP_TIMER, timer);
            }
            else
            {
                timer.ResetSeconds(seconds);
            }
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
    }
}
